"""
Unit tests for OpenAPI Route Ingestor.
"""

from prometheus.pentest.benchmark_app import app
from prometheus.pentest.models import HttpMethod
from prometheus.pentest.pr_ingestor import OpenAPIngestor


def test_parse_benchmark_openapi_spec():
    # Ingest real live FastAPI OpenAPI schema generated by the benchmark app
    spec = app.openapi()
    endpoints = OpenAPIngestor.parse_spec(spec)

    assert len(endpoints) >= 4

    # Verify BOLA candidates filter
    bola_candidates = OpenAPIngestor.filter_bola_candidates(endpoints)
    paths = {ep.path for ep in bola_candidates}
    assert "/api/v1/invoices/{invoice_id}" in paths
    assert "/api/v1/secure-invoices/{invoice_id}" in paths

    # Verify BFLA candidates filter
    bfla_candidates = OpenAPIngestor.filter_bfla_candidates(endpoints)
    bfla_methods = {(ep.path, ep.method) for ep in bfla_candidates}
    assert ("/api/v1/workspaces/{workspace_id}", HttpMethod.DELETE) in bfla_methods
